import{_ as i,H as a,f as o,i as t}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"芒伊木 Wiki - 响应式宽幅 Wiki 布局设计方案","description":"","frontmatter":{},"headers":[],"relativePath":"docs/superpowers/specs/2026-05-20-wiki-wide-layout-design.md","filePath":"docs/superpowers/specs/2026-05-20-wiki-wide-layout-design.md"}'),r={name:"docs/superpowers/specs/2026-05-20-wiki-wide-layout-design.md"};function d(s,e,n,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="芒伊木-wiki-响应式宽幅-wiki-布局设计方案" tabindex="-1">芒伊木 Wiki - 响应式宽幅 Wiki 布局设计方案 <a class="header-anchor" href="#芒伊木-wiki-响应式宽幅-wiki-布局设计方案" aria-label="Permalink to &quot;芒伊木 Wiki - 响应式宽幅 Wiki 布局设计方案&quot;">​</a></h1><h2 id="_1-目标与背景" tabindex="-1">1. 目标与背景 <a class="header-anchor" href="#_1-目标与背景" aria-label="Permalink to &quot;1. 目标与背景&quot;">​</a></h2><p><strong>目标</strong>：彻底消除 VitePress 在宽屏模式下产生的右侧巨大空白区域，提升信息展示密度。 <strong>背景</strong>：当前的布局虽然修复了组件冲突，但依然保留了 VitePress 默认的“现代博客”比例（正文居中，两侧留白巨大）。用户希望模仿专业 Wiki 的高密度排版，让内容撑满屏幕，并让右侧大纲紧贴正文。</p><h2 id="_2-架构与布局逻辑" tabindex="-1">2. 架构与布局逻辑 <a class="header-anchor" href="#_2-架构与布局逻辑" aria-label="Permalink to &quot;2. 架构与布局逻辑&quot;">​</a></h2><p>通过重写 VitePress 的 CSS 变量和局部容器样式，将布局中心点向右偏移，并释放正文宽度。</p><h3 id="_2-1-整体框架扩展" tabindex="-1">2.1 整体框架扩展 <a class="header-anchor" href="#_2-1-整体框架扩展" aria-label="Permalink to &quot;2.1 整体框架扩展&quot;">​</a></h3><ul><li><strong>全局宽度</strong>：设置 <code>--vp-layout-max-width</code> 为 <code>1600px</code>。</li><li><strong>内边距优化</strong>：在桌面端（<code>min-width: 960px</code>）下，减小 <code>.VPDoc</code> 的左右 <code>padding</code> 为 <code>32px</code>，从而让组件贴近屏幕边缘。</li></ul><h3 id="_2-2-正文区-content-area-深度扩容" tabindex="-1">2.2 正文区 (Content Area) 深度扩容 <a class="header-anchor" href="#_2-2-正文区-content-area-深度扩容" aria-label="Permalink to &quot;2.2 正文区 (Content Area) 深度扩容&quot;">​</a></h3><ul><li><strong>容器解锁</strong>：<code>.VPDoc .container</code> 设置 <code>max-width: 100% !important;</code>。</li><li><strong>阅读宽度限制</strong>：为了防止文字行过长导致阅读疲劳，设置正文文字容器（<code>.content-container</code>）的最大宽度为 <code>1200px</code>，但这部分空间包含了右侧浮动的卡片（Infobox）。</li><li><strong>左对齐倾向</strong>：确保正文区域在整体容器中不进行居中对齐，而是保持传统的 Wiki 左对齐风格，右侧留给浮动挂件和大纲。</li></ul><h3 id="_2-3-右侧大纲-aside-紧凑化" tabindex="-1">2.3 右侧大纲 (Aside) 紧凑化 <a class="header-anchor" href="#_2-3-右侧大纲-aside-紧凑化" aria-label="Permalink to &quot;2.3 右侧大纲 (Aside) 紧凑化&quot;">​</a></h3><ul><li><strong>宽度收窄</strong>：将原本占据较大比例的 <code>.aside</code> 宽度固定为 <code>220px</code>。</li><li><strong>位置紧贴</strong>：移除 <code>.aside</code> 容器上的 <code>padding-left</code> 和右侧可能的 <code>margin</code>，使其作为正文的紧凑附件存在。</li><li><strong>在大屏幕下的行为</strong>：当屏幕宽度足够时，Aside 应该紧贴在 1200px 宽的正文右侧，而不是飘到屏幕最右边。</li></ul><h2 id="_3-实现细节-css-关键点" tabindex="-1">3. 实现细节 (CSS 关键点) <a class="header-anchor" href="#_3-实现细节-css-关键点" aria-label="Permalink to &quot;3. 实现细节 (CSS 关键点)&quot;">​</a></h2><ul><li>使用 <code>@media (min-width: 1280px)</code> 和 <code>@media (min-width: 1440px)</code> 针对不同宽度的桌面端进行精细调整。</li><li>确保 <code>.VPContent.has-sidebar</code> 的逻辑依然稳固，不产生新的重叠。</li></ul><h2 id="_4-验证标准" tabindex="-1">4. 验证标准 <a class="header-anchor" href="#_4-验证标准" aria-label="Permalink to &quot;4. 验证标准&quot;">​</a></h2><ol><li><strong>空白消除测试</strong>：在 1080p 或更高分辨率的显示器上查看，右侧不应出现超过 100px 的无意义纯白区域。</li><li>** Aside 对齐测试**：右侧的“本页大纲”应紧贴在正文文字/卡片的右侧，视觉上属于同一信息块。</li><li><strong>响应式回归</strong>：确保在 768px 以下的移动端，布局依然能正确退回到单栏滚动模式。</li></ol><h2 id="_5-展望" tabindex="-1">5. 展望 <a class="header-anchor" href="#_5-展望" aria-label="Permalink to &quot;5. 展望&quot;">​</a></h2><p>此布局将为后续引入“高密度数据表格（WikiTable）”打下地盘基础。</p>',17)])])}const _=i(r,[["render",d]]);export{u as __pageData,_ as default};
